// Expand list of URLs into individual n8n items for sequential processing
const firstItem = $input.first()?.json || {};
let rawUrls = firstItem.urls || firstItem['Directory URLs'] || firstItem.directoryUrls || [];

if (typeof rawUrls === 'string') {
  rawUrls = rawUrls.split(/[\n,]/).map(u => u.trim()).filter(Boolean);
}

const items = [];
for (const u of rawUrls) {
  const trimmed = typeof u === 'string' ? u.trim() : '';
  if (trimmed && trimmed.startsWith('http')) {
    items.push({ json: { url: trimmed } });
  }
}

if (items.length === 0) {
  return [{ json: { url: '' } }];
}

return items;

const hunterResults = $input.all();
const extractorContacts = $('Gemini 3.5 Flash Lite Extractor').all().map(i => ({ ...i.json }));

return hunterResults.map((item, idx) => {
  let original = null;
  try {
    original = $('Needs Hunter.io?').itemMatching(idx)?.json;
  } catch (e) {}

  const resData = item.json?.data;
  const resMeta = item.json?.meta?.params;
  const fn = (resData?.first_name || resMeta?.first_name || original?.['First Name'] || '').trim().toLowerCase();
  const ln = (resData?.last_name || resMeta?.last_name || original?.['Last Name'] || '').trim().toLowerCase();
  const key = `${fn}_${ln}`;

  if (!original) {
    original = extractorContacts.find(c => `${(c['First Name']||'').toLowerCase()}_${(c['Last Name']||'').toLowerCase()}` === key) || item.json;
  }

  const updated = { ...original };
  if (resData && resData.email) {
    updated['Email'] = resData.email.trim();
    updated['Email Source'] = 'Hunter.io';
    updated['Enrichment Status'] = 'Enriched via Hunter.io';
  } else {
    if (!updated['Email']) updated['Email'] = '';
    updated['Enrichment Status'] = 'No Hunter.io Match';
  }
  return { json: updated };
});

function cleanHtml(html) {
  if (!html) return '';
  return html
    .replace(/<a[^>]*data-name=['"]([^'"]+)['"][^>]*data-domain=['"]([^'"]+)['"][^>]*>[\s\S]*?<\/a>/gi, ' Email: $1@$2 ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<a[^>]+href=['"]mailto:([^'"]+)['"][^>]*>[\s\S]*?<\/a>/gi, ' Email: $1 ')
    .replace(/<a[^>]+href=['"]tel:([^'"]+)['"][^>]*>[\s\S]*?<\/a>/gi, ' Phone: $1 ')
    .replace(/<(?:br|p|div|tr|li|h[1-6])[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .split('\n')
    .map(line => line.trim())
    .filter(Boolean)
    .join('\n');
}

function filterLargeTables(html, sourceUrl) {
  if (!html) return html;
  const trMatches = html.match(/<tr[^>]*>[\s\S]*?<\/tr>/gi);
  if (!trMatches || trMatches.length <= 80) return html;

  const headerTr = trMatches[0] || '';
  const rows = trMatches.slice(1);

  // If URL or page is focused on nursing, strictly isolate nursing rows
  const isNursing = /nurs/i.test(sourceUrl);
  if (isNursing) {
    const nursingRows = rows.filter(tr => /nurs/i.test(tr));
    if (nursingRows.length > 0) {
      return '<table>\n' + headerTr + '\n' + nursingRows.join('\n') + '\n</table>';
    }
  }

  // General department isolation if URL contains specific department path
  const urlMatches = sourceUrl.toLowerCase().match(/(?:department|school|college|division|program)s?\/([a-z0-9_-]+)/);
  if (urlMatches && urlMatches[1] && urlMatches[1].length > 3) {
    const deptKeyword = urlMatches[1].replace(/[-_]/g, '.*');
    try {
      const reg = new RegExp(deptKeyword, 'i');
      const deptRows = rows.filter(tr => reg.test(tr));
      if (deptRows.length > 0 && deptRows.length < rows.length) {
        return '<table>\n' + headerTr + '\n' + deptRows.join('\n') + '\n</table>';
      }
    } catch (e) {}
  }

  // Fallback: if rows mention nursing, prefer nursing
  const fallbackNursing = rows.filter(tr => /nurs/i.test(tr));
  if (fallbackNursing.length > 0 && fallbackNursing.length < rows.length) {
    return '<table>\n' + headerTr + '\n' + fallbackNursing.join('\n') + '\n</table>';
  }

  return html;
}

function extractDomain(url) {
  if (!url) return '';
  const match = url.match(/https?:\/\/(?:www\.)?([^\/\s:]+)/i);
  if (match) return match[1].toLowerCase();
  return url.replace(/^(?:https?:\/\/)?(?:www\.)?([^\/\s:]+).*/i, '$1').toLowerCase();
}

function getCleanDomain(domain) {
  const parts = (domain || '').replace(/^www\./, '').split('.');
  if (parts.length >= 2) return parts.slice(-2).join('.');
  return domain;
}

function getUniversity(domain, html) {
  const dom = (domain || '').toLowerCase().replace('www.', '');
  const unis = {
    'lagrange.edu': 'LaGrange College',
    'gntc.edu': 'Georgia Northwestern Technical College',
    'columbusstate.edu': 'Columbus State University',
    'asurams.edu': 'Albany State University',
    'georgiasouthern.edu': 'Georgia Southern University',
    'augusta.edu': 'Augusta University',
    'uga.edu': 'University of Georgia',
    'emory.edu': 'Emory University',
    'kennesaw.edu': 'Kennesaw State University',
    'gsu.edu': 'Georgia State University'
  };
  for (const [k, v] of Object.entries(unis)) {
    if (dom.includes(k)) return v;
  }
  const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (titleMatch) {
    const parts = titleMatch[1].replace(/\s+/g, ' ').trim().split(/[-|–—•]/);
    for (let i = parts.length - 1; i >= 0; i--) {
      const p = parts[i].trim();
      if (/university|college|institute/i.test(p)) return p;
    }
  }
  const core = dom.split('.')[0] || 'University';
  return core.charAt(0).toUpperCase() + core.slice(1) + ' University';
}

const allInputs = $input.all();
const finalContacts = [];
const seenKeys = new Set();
const cloudflareBlockedUrls = [];
const noContactsUrls = [];

let geminiApiKey = 'YOUR_GEMINI_API_KEY';
let hunterApiKey = 'YOUR_HUNTER_API_KEY';
try {
  const inputObj = $('Input URL List').first()?.json;
  if (inputObj?.geminiApiKey) geminiApiKey = inputObj.geminiApiKey;
  if (inputObj?.hunterApiKey) hunterApiKey = inputObj.hunterApiKey;
} catch (e) {}

for (let i = 0; i < allInputs.length; i++) {
  const item = allInputs[i];
  const dataObj = item.json;

  let sourceUrl = dataObj.url || '';
  if (!sourceUrl) {
    try {
      sourceUrl = $('Prepare Individual URLs').itemMatching(i)?.json?.url || '';
    } catch (e) {}
  }
  if (!sourceUrl) {
    try {
      sourceUrl = $('Prepare Individual URLs').first()?.json?.url || '';
    } catch (e) {}
  }

  const domain = extractDomain(sourceUrl);
  const cleanDomain = getCleanDomain(domain);

  let rawHtml = typeof dataObj.data === 'string' ? dataObj.data : (typeof dataObj === 'string' ? dataObj : JSON.stringify(dataObj));
  if (!rawHtml || rawHtml.length < 50) continue;

  const university = getUniversity(domain, rawHtml);

  // Detect Cloudflare WAF protection / 403 bot challenges
  const isCloudflare = (
    (typeof rawHtml === 'string' && (
      rawHtml.includes('challenges.cloudflare.com') ||
      rawHtml.includes('Just a moment...') ||
      rawHtml.includes('Enable JavaScript and cookies to continue') ||
      rawHtml.includes('403 Forbidden')
    )) ||
    (dataObj.error && (
      dataObj.error.status === 403 ||
      dataObj.error.statusCode === 403 ||
      String(dataObj.error.message || '').includes('403')
    ))
  );

  if (isCloudflare) {
    cloudflareBlockedUrls.push(sourceUrl || 'URL');
    continue;
  }

  if (!rawHtml || rawHtml.length < 50) {
    noContactsUrls.push(sourceUrl || 'URL');
    continue;
  }

  // Handle dynamic AJAX provider directories (e.g., GNTC)
  if (rawHtml.includes('pf_provider_list') || rawHtml.includes('wp-json/custom/v1/providers/list')) {
    try {
      const rootMatch = sourceUrl.match(/^(https?:\/\/[^\/]+)/i);
      const root = rootMatch ? rootMatch[1] : '';
      const apiUrl = root + '/wp-json/custom/v1/providers/list/';

      const optRegex = /<option[^>]+value=['"](\d+)['"][^>]*>([^<]+)<\/option>/gi;
      let om;
      const deptIds = [];
      while ((om = optRegex.exec(rawHtml)) !== null) {
        if (/nurs/i.test(om[2])) {
          deptIds.push({ id: om[1], name: om[2].trim() });
        }
      }
      if (deptIds.length === 0) deptIds.push({ id: '0', name: 'All' });

      for (const d of deptIds) {
        try {
          const apiRes = await this.helpers.httpRequest({
            method: 'POST',
            url: apiUrl,
            headers: {
              'Content-Type': 'application/x-www-form-urlencoded',
              'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
            },
            body: `filter_specialty=${encodeURIComponent(d.id)}&filter_practice=&filter_ft=1&filter_location=0&filter_query=`,
            timeout: 15000
          });
          const apiJson = typeof apiRes === 'string' ? JSON.parse(apiRes) : apiRes;
          if (apiJson && apiJson.html) {
            rawHtml += `\n\n=== DEPARTMENT: ${d.name} ===\n` + apiJson.html;
          }
        } catch (e) {}
      }
    } catch (e) {}
  }

  // Handle Angular / AJAX JSON feed directories (e.g., LaGrange College)
  const jsonFeedMatch = rawHtml.match(/(?:var\s+jsonFeed|jsonFeed)\s*=\s*['"]([^'"]+\.json[^'"]*)['"]/i) || rawHtml.match(/['"]([^'"]+directory[^'"]*\.json[^'"]*)['"]/i);
  if (jsonFeedMatch) {
    try {
      const feedRel = jsonFeedMatch[1].replace(/amp;/g, '');
      let feedUrl = feedRel;
      if (!feedRel.startsWith('http')) {
        const rootMatch = sourceUrl.match(/^(https?:\/\/[^\/]+)/i);
        const root = rootMatch ? rootMatch[1] : '';
        if (feedRel.startsWith('/')) {
          feedUrl = root + feedRel;
        } else {
          feedUrl = sourceUrl.replace(/\/[^\/]*$/, '/') + feedRel;
        }
      }

      const feedRes = await this.helpers.httpRequest({
        method: 'GET',
        url: feedUrl,
        headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
        timeout: 15000
      });

      const feedData = typeof feedRes === 'string' ? JSON.parse(feedRes) : feedRes;
      let items = [];
      if (feedData && typeof feedData === 'object') {
        for (const k of ['faculty', 'directory', 'staff', 'people', 'members', 'data']) {
          if (Array.isArray(feedData[k])) {
            items = feedData[k];
            break;
          }
        }
        if (items.length === 0 && Array.isArray(feedData)) {
          items = feedData;
        }
      }

      if (items.length > 0) {
        const cards = [];
        for (const it of items) {
          if (typeof it === 'object' && it !== null) {
            const fn = it.firstName || it.first_name || it.name || '';
            const ln = it.lastName || it.last_name || '';
            const fullName = ln ? `${fn} ${ln}`.trim() : fn;
            const title = it.title || it.position || it.role || '';
            const dept = it.departments || it.deptDisplay || it.department || '';
            const email = it.email || it.mail || '';
            const phone = it.phone || it.telephone || '';
            const office = it.office || it.location || it.campus || '';
            cards.push(`<div class="faculty-card"><h3>${fullName}</h3><p>Title: ${title}</p><p>Dept: ${dept}</p><p>Email: ${email}</p><p>Phone: ${phone}</p><p>Campus: ${office}</p></div>`);
          }
        }
        if (cards.length > 0) {
          rawHtml += '\n\n<!-- LOADED DYNAMIC JSON FEED -->\n' + cards.join('\n');
        }
      }
    } catch (e) {}
  }

  // If the directory is a master table with hundreds of multi-department faculty rows, isolate the target department rows
  const processedHtml = filterLargeTables(rawHtml, sourceUrl);
  let cleanText = cleanHtml(processedHtml);

  // Safeguard: only truncate if text is truly gigantic (> 300,000 chars)
  if (cleanText.length > 300000) {
    const lines = cleanText.split('\n');
    const relevantLines = lines.filter(l => /nurs|clinical|dean|chair|director|professor|instructor|faculty/i.test(l));
    if (relevantLines.length > 30) {
      cleanText = relevantLines.join('\n');
    }
    if (cleanText.length > 250000) {
      cleanText = cleanText.slice(0, 250000);
    }
  }

  // Deep crawl individual faculty profiles if main page lacks direct emails
  const emailMatches = cleanText.match(/[\w.-]+@[\w.-]+\.\w+/g) || [];
  if (emailMatches.length < 10) {
    const linkRegex = /<a\s+[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
    let match;
    const profileUrls = [];
    const seenP = new Set();
    const exclude = /cost|aid|tuition|admission|apply|athletics|news|event|calendar|privacy|terms|accessibility|map|catalog|degree|program|resource|international|board|record|dining|bookstore|job|portal|login|student|department|college/i;

    while ((match = linkRegex.exec(rawHtml)) !== null) {
      const href = match[1].trim();
      const text = match[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      if (!href || href.startsWith('#') || href.startsWith('javascript:') || href.startsWith('mailto:')) continue;

      let fullUrl = href;
      try {
        if (href.startsWith('http')) {
          fullUrl = href.split('?')[0].split('#')[0];
        } else if (href.startsWith('/')) {
          const rootMatch = sourceUrl.match(/^(https?:\/\/[^\/]+)/i);
          const root = rootMatch ? rootMatch[1] : '';
          fullUrl = root + href.split('?')[0].split('#')[0];
        } else {
          fullUrl = sourceUrl.replace(/\/[^\/]*$/, '/') + href.split('?')[0].split('#')[0];
        }
      } catch (e) { continue; }

      if (!fullUrl.toLowerCase().includes(domain.split('.')[0])) continue;
      if (seenP.has(fullUrl)) continue;

      const path = fullUrl.replace(/^https?:\/\/[^\/]+/i, '').toLowerCase();
      if (exclude.test(path) || exclude.test(text)) continue;

      const hasMarker = /\/(?:profiles?|faculty(?:-staff)?|people|person|bio|directory\/profile|employee)\//i.test(path);
      const isName = /^(?:dr\.|prof\.|mr\.|ms\.|mrs\.)\s+[A-Z][a-z]+/i.test(text) || (text.split(' ').length >= 2 && text.split(' ').length <= 4 && /^[A-Z]/.test(text));

      if (hasMarker || isName) {
        seenP.add(fullUrl);
        profileUrls.push({ url: fullUrl, name: text });
      }
    }

    if (profileUrls.length > 0) {
      const crawlLimit = Math.min(profileUrls.length, 25);
      const profileSections = [];
      for (let pIdx = 0; pIdx < crawlLimit; pIdx++) {
        const pObj = profileUrls[pIdx];
        try {
          const pRes = await this.helpers.httpRequest({
            method: 'GET',
            url: pObj.url,
            headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
            timeout: 8000
          });
          const pClean = cleanHtml(typeof pRes === 'string' ? pRes : JSON.stringify(pRes));
          profileSections.push(`=== FACULTY PROFILE: ${pObj.name} (${pObj.url}) ===\n` + pClean.slice(0, 1500));
        } catch (e) {}
      }
      if (profileSections.length > 0) {
        cleanText += '\n\n=== INDIVIDUAL FACULTY PROFILE BIO PAGES ===\n\n' + profileSections.join('\n\n');
      }
    }
  }

  const systemPrompt = `You are an elite data extraction specialist for higher education and university faculty directories.
Task:
Extract ALL Nursing faculty, leadership, instructors, and staff members from the provided webpage content and individual profile bio sections into an Excel-ready dataset.

Scope & Selection Criteria:
1. Include all individuals affiliated with the School of Nursing, Department of Nursing, or Nursing programs.
2. Include anyone holding nursing or clinical healthcare credentials/degrees (e.g. RN, BSN, MSN, DNP, PhD in Nursing, APRN, FNP, CNE, AGNP, CNS) or teaching nursing courses.
3. Include nursing administrative and student support staff (e.g. Chairs, Directors, Program Coordinators, Skills Lab Coordinators, Advisors).
4. If the page contains a master university directory featuring multiple departments, extract ONLY the individuals belonging to Nursing or Health Professions.
5. If individual faculty profile bio pages are appended, extract their exact email, direct phone, office location, and education degrees/credentials from their profile section.
6. Extract EVERY single matching person without truncation, omission, or placeholders.

Field Specifications:
- "first_name": Clean first name (remove honorifics such as Dr., Prof., Mr., Ms., Mrs.).
- "last_name": Last name.
- "credentials": All post-nominal degrees, licenses, and certifications (e.g., PhD, DNP, MSN, BSN, RN, FNP-C, APRN). Leave empty string "" if none found.
- "title": Complete job title, faculty rank, or administrative role.
- "campus": Specific campus name, branch, or office location. If specific campus detail is not available, use the University name: ${university}.
- "email": Institutional email address. If not found, leave empty string "".
- "phone": Direct or office phone number. If not found, leave empty string "".

Output Format:
Return ONLY a valid, parseable JSON array of objects with keys:
"first_name", "last_name", "credentials", "title", "campus", "email", "phone"`;

  const geminiUrl = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash-lite:generateContent?key=' + geminiApiKey;

  let geminiRes = null;
  let lastErr = null;

  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      geminiRes = await this.helpers.httpRequest({
        method: 'POST',
        url: geminiUrl,
        headers: { 'Content-Type': 'application/json' },
        body: {
          contents: [
            {
              parts: [
                {
                  text: systemPrompt + '\n\nWebpage Content:\n' + cleanText
                }
              ]
            }
          ],
          generationConfig: {
            responseMimeType: 'application/json',
            temperature: 0.0,
            maxOutputTokens: 8192
          }
        },
        json: true,
        timeout: 60000
      });
      if (geminiRes) break;
    } catch (err) {
      lastErr = err;
      if (attempt < 2 && (err.message.includes('429') || err.message.includes('rate'))) {
        await new Promise(resolve => setTimeout(resolve, 4000 * (attempt + 1)));
      } else {
        break;
      }
    }
  }

  if (!geminiRes && lastErr) {
    throw new Error('Gemini extraction failed: ' + lastErr.message);
  }

  const candidateText = geminiRes?.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
  let parsedContacts = [];
  try {
    parsedContacts = JSON.parse(candidateText);
  } catch (e) {
    parsedContacts = [];
  }

  if (Array.isArray(parsedContacts) && parsedContacts.length === 0) {
    noContactsUrls.push(sourceUrl || 'URL');
  }
  if (Array.isArray(parsedContacts)) {
    for (const c of parsedContacts) {
      const fn = (c.first_name || '').trim();
      const ln = (c.last_name || '').trim();
      const em = (c.email || '').trim().toLowerCase();
      const camp = (c.campus || '').trim();
      const key = `${fn}_${ln}`.toLowerCase();

      if (seenKeys.has(key)) continue;
      if (fn || ln || em) {
        seenKeys.add(key);
        finalContacts.push({
          json: {
            'First Name': fn,
            'Last Name': ln,
            'Credentials': (c.credentials || '').trim(),
            'Title': (c.title || '').trim(),
            'Campus': (!camp || camp.toLowerCase() === 'none') ? university : camp,
            'Email': em,
            'Phone': (c.phone || '').trim(),
            'Source URL': sourceUrl,
            'Domain': domain,
            'Clean Domain': cleanDomain
          }
        });
      }
    }
  }
}

if (finalContacts.length > 0) {
  return finalContacts;
}

if (cloudflareBlockedUrls.length > 0) {
  return [{
    json: {
      isStatusMessage: true,
      title: 'Access Blocked (Cloudflare Protection)',
      message: 'Access blocked: The directory URL (' + cloudflareBlockedUrls.join(', ') + ') is protected by Cloudflare bot security (HTTP 403 Forbidden). Automatic access is restricted by the institution.',
      reason: 'cloudflare_blocked'
    }
  }];
}

return [{
  json: {
    isStatusMessage: true,
    title: 'No Nursing Contacts Found',
    message: 'No nursing faculty or staff contacts were found on the provided directory page(s). Please verify the directory link or select a page containing the nursing department.',
    reason: 'no_nursing_found'
  }
}];
